.load /Users/zdkadiev/Repos/letopis/.artifacts/issue-65/2026-11-06-native-followup/oracle-vec1.dylib sqlite3_extension_init
attach '/Users/zdkadiev/Repos/letopis/.artifacts/issue-65/benchmark-10k-run/fixture/repository/.letopis/vectors.db' as vec;
select n.uri as id,v.distance as metric
from vec.vector_index(X'','{K:10000}') v
join vec.vector_keys k on k.row_id=v.rowid join nodes n on n.search_hash=k.search_hash
where n.kind <> 'source' order by v.distance,n.uri limit 100;
